          "comment": "Poor win record but lurks on a dangerous mark and this intermediate trip could be ideal",
          "spotlight": "Poor strike-rate and has flattered to deceive in the past, but he's on a good mark on this winter's AW best and a recent 5f run here should have sharpened him up; has run well for Saffie Osborne in the past and this intermediate trip could suit him well; lively outsider.",
