              "distance_f": "7",
              "distance_y": "1540",
              "quote": "All Not Just Yet's form was on slow or soft ground so we thought the ground might be too quick. He was slowly away but got a good position. I probably got there too soon, he didn't do a whole pile in front but he is nice and done it well. Hopefully now he can step forward now having proven himself on that ground. - Adam Caffrey, jockey."
