          "quotes": [],
          "stable_tour": [
            {
              "quote": "He was unlucky at Bath last time when he got turned sideways. At least with Fact Or Fable you can semi-predict whenever he's going to win but old Uther is more unpredictable. He won three times in a week just before he turned eight. He's versatile at any trip from a mile and a quarter to two and a quarter miles. He enjoys it and pays his way every year, which is nice. I wouldn't mind a few more horses like him. I raced him in France a fair bit as a two- and three-year-old and he had won €98,000 in prize-money and was still a maiden. 04-07-24"
            }
          ],
