          "comment": "All eight of his wins have been at this track; has been running well; drops back to 1m",
          "spotlight": "All eight wins have been at this track, including two over this C&D; didn't get the breaks when a close fourth here last month and shaped as if still in form when third of six here (also 1m2f) three weeks ago; drops back to 1m with obvious claims.",
          "quotes": [
            {
              "date": "2022-05-24",
              "horse": "Blue Hero",
              "horse_id": "hrs_21685699",
              "race": "Sky Sports Racing Sky 415 Apprentice Handicap",
              "race_id": "rac_10545327",
              "course": "Bath",
              "course_id": "crs_130",
              "distance_f": "11.5",
              "distance_y": "2557",
              "quote": "I was expecting a good performance from Blue Hero, although the trip was a question mark. We thought he'd get it, but he's improved from a three-year-old. He's a little bit tricky in his head, but he's physically improved from last year. He likes it here, but doesn't have to stay here - it's coincidence we run a lot here. I was worried the ground would be on the soft side, but he's handled it well - Adrian Wintle, trainer."
            }
          ],
