          "comment": "Gained his third C&D win when winning by a nose three weeks ago; back up in grade; claims",
          "spotlight": "Well below best when beaten 14l at Chepstow in June but he gained his third C&D success (on firm and good to firm) when winning by a nose in a classified event three weeks ago; back up in grade; claims.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "I've got two lovely old campaigners who are half-brothers - Fact Or Fable and Uther Pendragon. Between the two of them, they've won just short of £200,000 in prize-money. They always turn up and probably on the days you'd don't expect them to win, they do. They're characters in the yard and keep everybody on their toes who rides them. They're owned by the same people - Wendy and Stuart Jarrett - who get so much fun out of it. It's what the game's about. Wendy and Stuart have point-to-pointers as well and they absolutely love their racing. They come from the Bath area and that's why, when you see them, they'll always turn up at Bath and Chepstow. They're the sort of owners racing needs, who are in it just for the love of the sport. 04-07-24"
            }
          ],
