          "comment": "Fast mare who comes here in top form; ideally drawn to attack; should be involved again",
          "spotlight": "Fast mare who comes here in top form, winning at Ripon last month and then a good second at Musselburgh two weeks ago (holds Wee Mary); ideally drawn to attack and she has been placed in four of her eight C&D runs; should be in the thick of it again.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "She won twice for us over 5f in 2023, both times at Musselburgh, and was placed there three times last season. She loves sharp tracks like Musselburgh and Catterick. She's down to a winnable mark of 48 and I'm hopeful she'll be able to win again and pick up prize-money throughout the year. She goes really well for claimers and likes quickish ground. 21-05-25"
            }
          ],
