              "race": "Roflow Environmental Engineering Specialist Ventilation Services Handicap",
              "race_id": "rac_11594297",
              "course": "Newcastle (AW)",
              "course_id": "crs_35178",
              "distance_f": "7",
              "distance_y": "1554",
              "quote": "It's been a long time between drinks for Benacre but he's a bit of a favourite at home and I'm delighted to see him get his head back in front. He had a frustrating campaign last year and, in hindsight when we were trying different things, we were going in the wrong direction in terms of trip. After his comeback run at Chelmsford this year we thought coming back to seven [furlongs] was worth a try - Charlie Johnston, trainer, speaking to Sky Sports Racing."
