          "comment": "Off the mark for the season on AW last time; just as effective on turf; a possible",
          "spotlight": "Off the mark for the season when scoring off 4lb lower at Chelmsford last time (7f, standard to soft); two previous wins were over 7f/1m on good to firm; a possible.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "He won very well at Haydock last year on his second start for us, then he wasn't quite right in the summer - there were a few in the yard under a bit of a cloud. We rested him quite early and he went back to his owner-breeder. He's back in training now and I see no reason why he can't build on that win at Haydock, where he looked like a horse with a lot of natural ability. 20-03-24"
            }
          ],
