          "comment": "Finally registered a turf win on latest start, doing so in clearcut fashion over 1m6f here",
          "spotlight": "Two Ffos Las races were among his eight seconds on turf before he finally registered a turf win on latest start, in clearcut fashion when coming from last of six in a 1m6f contest here (good to soft); firmer ground should be fine; back up 5lb but stays 2m too and he faces even fewer rivals today.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "He's a quirky old soldier. He does his best not to win, but did win one race early last season at Chelmsford. He was a bit more backward when he came in this year, so we gave him a run to straighten him up. Hopefully he'll win his one race again, but he's very good at coming second. He's entered at Lingfield and Chepstow later in the week. 29-04-25"
            }
          ],
