              "quote": "He ran once in an Irish point-to-point, and the third has come out and won since. He should be out shortly, whether it's in a bumper or over hurdles, I'm not yet sure. We had him at the backend of last season and he goes nicely at home. He'll probably want a trip. 21-11-22"
