          "comment": "In good form in September 2023 but tricky to weigh up after long absence",
          "spotlight": "Won pretty easily by 12l off a 2lb lower mark in September 2023, his third chase success, but is tricky to weigh up on this first appearance for 660 days; market helpful.",
          "quotes": [
            {
              "date": "2020-12-01",
              "horse": "Glajou",
              "horse_id": "hrs_20424894",
              "race": "Sky Sports Racing Sky 415 Novices' Limited Handicap Chase (GBB Race)",
              "race_id": "rac_10017280",
              "course": "Southwell",
              "course_id": "crs_1586",
              "distance_f": "16",
              "distance_y": "3482",
              "quote": "Glajou is definitely improving and is such a big four-year-old. He's getting stronger and better and learning how to race. He could make into a nice horse. It was a solid race at Chepstow last time and he's going the right way.  Harry Cobden, jockey."
            }
          ],
          "stable_tour": [
            {
              "quote": "He won over fences last year but is still qualified for novice hurdles and will go that route. He was slightly frustrating last season and didn't always find that much off the bridle but he's still only five and I hope he will finish his races better now he's another year stronger. 08-11-21"
            }
          ],
