          "comment": "Very much had the run of things at Warwick but this mare looks on the upgrade",
          "spotlight": "Has won two of her three starts following a wind operation, making all for a narrow win off 4lb lower at Warwick last time (2m, good); very much had the run of things that day but looks on the upgrade.",
          "quotes": [
            {
              "date": "2025-04-19",
              "horse": "Soleil d'Arizona",
              "horse_id": "hrs_35741643",
              "race": "Watch On Racing TV Mares' Maiden Hurdle (GBB Race)",
              "race_id": "rac_11577592",
              "course": "Haydock",
              "course_id": "crs_598",
              "distance_f": "15.5",
              "distance_y": "3444",
              "quote": "Soleil d'Arizona is not great to watch and Harry confirmed it wasn't great to ride her either. She's got a few little issues that we've had to iron out but if you watch her after the last she really poked her nose out and really wanted to do it. If we can help her through the spring time and into the summer, the easier weather will be easier for her and hopefully she can win a couple more - Dan Skelton, trainer."
            }
          ],
          "stable_tour": [
            {
              "quote": "A tidy sort for mares' novice hurdles. She whizzed round Exeter first time out but just got caught on the line, so I think a tighter track would suit her better, but she loves her jumping and shows plenty of pace. 12-11-24"
            }
          ],
