          "comment": "Progressive on AW since autumn and won comfortably on handicap hurdle debut",
          "spotlight": "Progressive on the AW since switching to current stable in the autumn (five wins) and beat three rivals comfortably to make winning handicap hurdle debut at Southwell (2m, good) laat month; unable to justify skinny odds when only third soon afterwards but remains of strong interest.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "Freddy Tylicki sourced him privately off Tracy Waggott for me. He's owned by some friends of mine. He's two from two for us and we'll now probably sit and wait and have a good look at one of these bonuses with him in January. I still think he's got plenty of potential and, being by Frankel, he's a strong stayer. He's just a good, sound horse. He's run once over hurdles and we'll go hurdling with him again over the summer. 01-01-25"
            }
          ],
