          "comment": "Placed twice on the Flat last month and has possibilities on this return to hurdling",
          "spotlight": "Pulled up on latest hurdling start in February but the form of his Market Rasen second (2m, good to soft) a fortnight earlier worked out well, and he was placed twice on the Flat last month; a possible.",
          "quotes": [
            {
              "date": "2024-10-19",
              "horse": "Morandi Second",
              "horse_id": "hrs_28027727",
              "race": "Go Racing In Yorkshire Future Stars Apprentice Handicap",
              "race_id": "rac_11398933",
              "course": "Catterick",
              "course_id": "crs_260",
              "distance_f": "14",
              "distance_y": "3052",
              "quote": "Morandi Second loved the ground and settled beautifully when I got my own way in front and was able to dictate. When I went for him coming to the bend, he changed his legs and took off for me. This ground is very wet and it's hard to make ground up - Joe Leavy, jockey."
            }
          ],
          "stable_tour": [
            {
              "quote": "He ran a great race at Sedgefield last time when he just got caught on the line. He won on the Flat the time before and got confidence from it. We're going to drop him back in trip and I think he's well handicapped over hurdles. He had issues but we've found the key to him and he's in great form. He's a different horse now. 11-12-24"
            }
          ],
