          "comment": "Had ground excuse last time but is 0-12 over hurdles now and not always enthusiastic",
          "spotlight": "Kept on for fourth at Cartmel (2m6f, good) in May, after a layoff, and may not have been suited by the soft ground when below form there last month but she's 0-12 over hurdles now and doesn't always look enthusiastic.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "I really like her. She's been so lightly raced, she's never had the chance to have a clear run. She's a point-to-point winner who got quite ill last season, so her campaign was cut short. She wants good ground, so it probably wasn't a bad thing and she returned with a good run at Musselburgh in November when she was second to Autumn Return, who is now rated 119. She's been firing on all cylinders at home but we've had nowhere to go with her as she's very ground-dependent. We'll have a lot of fun with her in the spring and summer and hopefully she's a winner in waiting for the Coral Racing Club. 24-01-24"
            }
          ],
