          "comment": "0-19 on turf but runner-up here in two of his last four, including C&D; can go well again",
          "spotlight": "Nine-time AW winner whose last success was off 2lb higher at Lingfield (5f) in February; 0-19 on turf but he's finished runner-up here in two of his last four runs, including when having three of these behind over C&D in June; respectable effort over 5f last time and should go well again back up in trip.",
