          "comment": "Long losing run on turf; low key for new yard but down weights and return to 7f will suit",
          "spotlight": "Losing turf run goes back nearly two years and he's achieved little over 6f in 2025 for this yard, but he's done his winning over 7f and has dropped 9lb since the spring; interesting to see what the market says with cheekpieces fitted (has run well in a hood).",
          "quotes": [
            {
              "date": "2023-09-23",
              "horse": "Ararat",
              "horse_id": "hrs_31966298",
              "race": "Turners Handicap",
              "race_id": "rac_11021764",
              "course": "Newmarket",
              "course_id": "crs_988",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Ararat is a talented horse who has underachieved but he's capable on his day - David Simcock, trainer"
            },
            {
              "date": "2023-06-24",
              "horse": "Ararat",
              "horse_id": "hrs_31966298",
              "race": "Racing TV Handicap",
              "race_id": "rac_10945987",
              "course": "Newmarket (July)",
              "course_id": "crs_4524",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Ararat has promised to win in the past so it was nice he could get his head in front. We've tried him on soft ground as he's German-bred, but he likes it quicker-Bruce Raymond, owner's racing manager."
            }
          ],
          "stable_tour": [
            {
              "quote": "He's been an underachiever. He's always been talented but lets us down more times than not. He looked very good and produced a very good time figure at Chelmsford. That was a nice prize. We'll look to run him on fast ground or on the all-weather between now and the end of the season. He's entered at Ascot on Friday, a seven-furlong classified race, so he might go there. 04-09-24"
            }
          ],
