            {
              "quote": "This colt was extremely well bought at the Deauville breeze-up and after some encouraging work he made a lovely start at Newbury when third to Sketch over 6f. I think that was a nice race and he came out of it well. I sent him to Salisbury last week for his second run and he ran very well for a long way before tiring in the final furlong. He's better than that and will be winning sooner rather than later. 17-08-23"
            }
