          "comment": "Below best last twice but previous consistent form gives him major claims",
          "spotlight": "Overcame a slow start and trouble in running to win Roscommon handicap in May; hasn't counted twice since but overall profile gives him major claims if avoiding a slow start; draw not ideal.",
          "quotes": [
            {
              "date": "2024-11-13",
              "horse": "Shoot To Kill",
              "horse_id": "hrs_19208000",
              "race": "DKITSU Race Day At Dundalk Handicap",
              "race_id": "rac_11461216",
              "course": "Dundalk (AW)",
              "course_id": "crs_29588",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Shoot To Kill has been slipping down the weights. He had the inside draw and Donagh was able to keep it simple once he got a lead. He's a horse with plenty of talent and hopefully that will have got his confidence back - Stephen Thorne, trainer."
            },
            {
              "date": "2022-01-22",
              "horse": "Shoot To Kill",
              "horse_id": "hrs_19208000",
              "race": "MansionBet Proud Partners Of The AWC Handicap",
              "race_id": "rac_10419305",
              "course": "Lingfield (AW)",
              "course_id": "crs_10218",
              "distance_f": "8",
              "distance_y": "1761",
              "quote": "Shoot To Kill did that well and may well get further in time. He pulls up a bit when in front so may well have more to give - Darragh Keenan, jockey."
            }
          ],
          "stable_tour": [
            {
              "quote": "He is a slightly frustrating customer as he is a very good worker at home but does not always transfer that ability to the racecourse. He put his best foot forward last month when winning at Chelmsford over 6f and in fairness to the horse he has been unlucky at times, but he has this propensity to throw away his good luck on occasions. His subsequent effort at Wolverhampton was not his fault as he was almost knocked over. We will be aiming him at 6f handicaps on good, fast summer ground and I am sure there is a nice race to be won. We may dip him in the deep end occasionally as he could go well in one of those races off a featherweight. 14-04-21"
            }
          ],
