              "quote": "Mojave River is a lovely filly with a good attitude. She was bought by Stuart Boman of Blandford Bloodstock at the breeze-ups and she had the benefit of that experience coming here today. I'm delighted to win a good pot for Go Racing, who have been very good supporters of mine. The horses race here for their two- and three-year-old seasons and then they go to Australia most likely to race later on. This looks a nice filly with stakes potential this season - Joseph O'Brien, trainer."
